            "dne" | "doesnotexist" => "DNE",
            "∞" | "+∞" | "\\infty" | "+\\infty" | "infinity" | "+infinity" => "infinity",
            "-∞" | "-\\infty" | "-infinity" => "-infinity",
            "<" => "<",
