            "≤" | "<=" | "\\le" | "\\leq" => "<=",
            "≥" | ">=" | "\\ge" | "\\geq" => ">=",
            "=" => "=",
            "≠" | "!=" | "\\ne" | "\\neq" => "!=",
            _ => return None,
        }
        .into(),
    )
}
